  for (const s of sel){ const e=document.querySelector(s); if(!e) continue;
    const before = getComputedStyle(e); const b={o:before.outlineStyle+' '+before.outlineWidth+' '+before.outlineColor, bs:before.boxShadow, bc:before.borderColor};
    e.focus(); await new Promise(r=>setTimeout(r,50));
    const a=getComputedStyle(e);
    out.push({s, active: document.activeElement===e, fv: e.matches(':focus-visible'), before:b, after:{o:a.outlineStyle+' '+a.outlineWidth+' '+a.outlineColor, bs:a.boxShadow, bc:a.borderColor}});
  }
  return out;
}"}

